from itertools import permutations
from fractions import Fraction as F
rots=[lambda x,y:(x,y),lambda x,y:(-y,x),lambda x,y:(-x,-y),lambda x,y:(y,-x)]
# any sequence of axis scalings (positive) and 90-degree rotations equals diag(sx,sy) after some rotation
def reachable(tri):
    for r in rots:
        V=[r(*p) for p in orig]
        for W in permutations(tri):
            sx=sy=None; ok=True
            for (x,y),(u,w) in zip(V,W):
                for c,t,name in ((x,u,'x'),(y,w,'y')):
                    if c==0:
                        if t!=0: ok=False
                    else:
                        s=F(t,1)/c
                        if s<=0: ok=False
                        if name=='x':
                            if sx is None: sx=s
                            elif sx!=s: ok=False
                        else:
                            if sy is None: sy=s
                            elif sy!=s: ok=False
            if ok: return True
    return False
m=[i for i,o in enumerate(opts) if reachable(o)]
assert len(m)==1
ans='ABCD'[m[0]]
